'use strict';
(()=>{const button=document.getElementById('music');let audio=null,master=null,filter=null,timer=null,next=0,step=0,busy=false;const notes=[48,55,60,62,64,67,69,72],chords=[[48,55,64],[45,52,60],[41,48,57],[43,50,62]];function tone(midi,start,duration,volume){const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=440*Math.pow(2,(midi-69)/12);g.gain.setValueAtTime(0,start);g.gain.linearRampToValueAtTime(volume,start+.2);g.gain.exponentialRampToValueAtTime(.0001,start+duration);o.connect(g);g.connect(filter);o.start(start);o.stop(start+duration+.1);o.onended=()=>{o.disconnect();g.disconnect()};}function schedule(){while(next<audio.currentTime+1.2){if(step%8===0)chords[Math.floor(step/8)%4].forEach(n=>tone(n,next,6,.055));if(step%2===0&&Math.random()>.18)tone(notes[Math.floor(Math.random()*notes.length)]+12,next,3.5,.035);next+=.85;step++;}}button.onclick=async()=>{if(busy)return;busy=true;try{if(timer){clearInterval(timer);timer=null;master.gain.cancelScheduledValues(audio.currentTime);master.gain.setTargetAtTime(0,audio.currentTime,.08);await audio.suspend();button.setAttribute('aria-pressed','false');button.textContent='♫ Música';return;}if(!audio){const Context=window.AudioContext||window.webkitAudioContext;if(!Context)throw Error();audio=new Context();master=audio.createGain();master.gain.value=0;master.connect(audio.destination);filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=1800;filter.connect(master);const delay=audio.createDelay(2),feedback=audio.createGain(),wet=audio.createGain();delay.delayTime.value=.63;feedback.gain.value=.25;wet.gain.value=.22;filter.connect(delay);delay.connect(feedback);feedback.connect(delay);delay.connect(wet);wet.connect(master);}await audio.resume();master.gain.setTargetAtTime(.65,audio.currentTime,.3);next=audio.currentTime+.1;schedule();timer=setInterval(schedule,250);button.setAttribute('aria-pressed','true');button.textContent='♫ Apagar música';}catch{button.textContent='♫ Reintentar música';if(typeof toast==='function')toast('No se pudo iniciar el audio. Pulsa de nuevo para intentarlo.')}finally{busy=false;}};window.addEventListener('pagehide',()=>{clearInterval(timer);if(audio)audio.close();});})();
